-- Local Mission BI mart stand-in (Postgres). Replaces Trino mission_marts for Local UI.
CREATE SCHEMA IF NOT EXISTS reporting;

DROP TABLE IF EXISTS reporting.metric_series;
DROP TABLE IF EXISTS reporting.pipeline_snapshot;

CREATE TABLE reporting.pipeline_snapshot (
  captured_at timestamptz NOT NULL,
  active_dataset_version text NOT NULL,
  raw_landed_count int NOT NULL,
  curation_stage text NOT NULL
);

CREATE TABLE reporting.metric_series (
  time timestamptz NOT NULL,
  dashboard_id text NOT NULL,
  metric_id text NOT NULL,
  value double precision NOT NULL,
  mission_id text NOT NULL DEFAULT 'mission-alpha'
);
CREATE INDEX ON reporting.metric_series (dashboard_id, metric_id, time);

CREATE OR REPLACE VIEW reporting.fct_curation_health AS SELECT time, metric_id, value, mission_id FROM reporting.metric_series WHERE dashboard_id = 'curation_health';
CREATE OR REPLACE VIEW reporting.fct_data_quality AS SELECT time, metric_id, value, mission_id FROM reporting.metric_series WHERE dashboard_id = 'data_quality_drift';
CREATE OR REPLACE VIEW reporting.fct_security_compliance AS SELECT time, metric_id, value, mission_id FROM reporting.metric_series WHERE dashboard_id = 'security_compliance';
CREATE OR REPLACE VIEW reporting.fct_mission_agent_eval AS SELECT time, metric_id, value, mission_id FROM reporting.metric_series WHERE dashboard_id = 'mission_agent_evaluation';
